function _gaLayoutDupZona(){var sel=LayoutMap._edSel;if(!sel){showToast('Selecciona una zona (clic)','error');return;}var z=_gaLayoutZonas.find(function(x){return x.cod===sel});if(!z)return;var nz=Object.assign({},z);nz.cod=_gzAutoCode(z.tipo);nz.pos_x=(z.pos_x||0)+30;nz.pos_y=(z.pos_y||0)+20;nz.nombre=z.nombre+' (copia)';_gaLayoutZonas.push(nz);_glmR();showToast(nz.cod+' duplicado','success');}
gaRenderLayout=function(){var el=document.getElementById('gaLayoutCount');if(el)el.textContent=(_gaLayoutZonas||[]).length+' zonas';if(document.getElementById('glmCanvas')){_glmR();return;}LayoutMap._edCb=function(a,cod){if(a==='edit'){var i=_gaLayoutZonas.findIndex(function(x){return x.cod===cod});if(i>=0)gaLayoutEditZonaIdx(i);}};LayoutMap.render('gaLayoutCanvas',_gaLayoutZonas,{turno:_gaLayoutFilter||'ambos',selected:{},editable:true,onToggle:function(){}});};
gaLoadLayout=async function(){var sede=_gaSedeActiva||document.getElementById('gaSedeSelect')?.value;if(!sede)return;try{_gaLayoutZonas=await API.get('/layout?sede='+sede)||[];}catch(e){_gaLayoutZonas=[];}gaRenderLayout();};
gaLayoutSave=async function(){var sede=_gaSedeActiva||document.getElementById('gaSedeSelect')?.value;if(!sede){showToast('Selecciona sede','error');return;}var cId=document.getElementById('glmCanvas')?'glmCanvas':'gaLayoutCanvas';var cv=document.querySelector('#'+cId+' #lm-cv')||document.querySelector('#'+cId+' .layout-canvas');if(cv){_gaLayoutZonas.forEach(function(z){var el=cv.querySelector('[data-cod="'+z.cod+'"]');if(el){z.pos_x=parseFloat(el.style.left)/100*800;z.pos_y=parseFloat(el.style.top)/100*580;var w=parseFloat(el.style.width),h=parseFloat(el.style.height);if(w>0)z.ancho=w/100*800;if(h>0)z.alto=h/100*580;}});}var r=await API.put('/layout/bulk',{sede:sede,zonas:_gaLayoutZonas});if(r)showToast('Layout guardado','success');};
gaLayoutDeleteZona=function(idx){var z=_gaLayoutZonas[idx];if(!z)return;showConfirm('Eliminar?',z.cod+' '+z.nombre,function(){var prefix=z.cod.replace(/[0-9]/g,'');_gaLayoutZonas.splice(idx,1);var count=0;_gaLayoutZonas.forEach(function(zz){if(zz.cod.replace(/[0-9]/g,'')===prefix){count++;zz.cod=prefix+String(count).padStart(2,'0');}});_glmR();showToast('Eliminado','success');});};

