function _gzSetFreq(v){document.getElementById('gzFreqCustomWrap').style.display=v===-1?'':'none';document.getElementById('gzDiasWrap').style.display=(v===7||v===14)?'':'none';if(v!==-1)document.getElementById('gzFreq').value=v;document.querySelectorAll('.gz-freq-btn').forEach(function(b){var bv=parseInt(b.dataset.val),s=bv===v;b.style.border='1.5px solid '+(s?'var(--navy)':'transparent');b.style.background=s?'rgba(46,62,110,.08)':'var(--s3)';b.style.color=s?'var(--navy)':'var(--text3)';});}
