  h+='<div class="field" style="margin-bottom:6px"><label>Tipo</label><select id="gzTipo" onchange="_gzTipoChange()" style="width:100%">';_ZONA_TIPOS.forEach(function(t){h+='<option value="'+t.v+'"'+(d.tipo===t.v?' selected':'')+'>'+t.l+'</option>';});h+='</select></div>';
  h+='<div style="display:flex;gap:6px;margin-bottom:6px"><div class="field" style="flex:1;margin:0"><label>Nombre</label><input type="text" id="gzNombre" value="'+(d.nombre||'')+'"></div><div class="field" style="width:65px;margin:0"><label>Cod.</label><input type="text" id="gzCod" value="'+(d.cod||'')+'" readonly style="font-weight:700;text-align:center;background:var(--s3);cursor:not-allowed"></div></div>';
  h+='<div style="margin-bottom:6px"><label style="font-size:11px;font-weight:600;color:var(--text2);display:block;margin-bottom:3px">Turno</label><div style="display:flex;gap:4px">';
  [{v:'ambos',l:'Ambos'},{v:'mañana',l:'AM'},{v:'tarde',l:'PM'}].forEach(function(t){var s=(d.turno||'ambos')===t.v;h+='<button type="button" class="gz-t-btn" data-val="'+t.v+'" onclick="_gzSelTurno(this)" style="flex:1;padding:6px;border-radius:6px;border:1.5px solid '+(s?_TC[t.v]:'transparent')+';background:'+(s?_TC[t.v]+'22':'var(--s3)')+';cursor:pointer;font-size:10px;font-weight:600;color:'+(s?_TC[t.v]:'var(--text3)')+'">'+t.l+'</button>';});
  h+='</div><input type="hidden" id="gzTurno" value="'+(d.turno||'ambos')+'"></div>';
  h+='<div style="margin-bottom:6px"><label style="font-size:11px;font-weight:600;color:var(--text2);display:block;margin-bottom:3px">Nivel</label><div style="display:flex;gap:4px">';
  _ZONA_NIVELES.forEach(function(n){var s=(d.nivel||'piso')===n.v;h+='<button type="button" class="gz-n-btn" data-val="'+n.v+'" onclick="_gzSelNivel(this)" style="flex:1;padding:5px;border-radius:6px;border:1.5px solid '+(s?'var(--navy)':'transparent')+';background:'+(s?'rgba(46,62,110,.08)':'var(--s3)')+';cursor:pointer;font-size:9px;font-weight:600;color:'+(s?'var(--navy)':'var(--text3)')+'">'+n.l+'</button>';});
  h+='</div><input type="hidden" id="gzNivel" value="'+(d.nivel||'piso')+'"><div id="gzSobreWrap" style="display:'+(d.nivel==='sobre'?'':'none')+';margin-top:4px"><label style="font-size:10px;color:var(--text3);display:block;margin-bottom:2px">Sobre cual mueble?</label><input type="text" id="gzSobreDisplay" value="'+sobreDisp+'" readonly onclick="_gzOpenSobrePicker()" placeholder="Clic para elegir" style="width:100%;padding:8px 12px;border-radius:8px;border:1.5px solid var(--border);font-size:12px;cursor:pointer;background:#fff"><input type="hidden" id="gzSobreCod" value="'+(d.sobre_cod||'')+'"></div></div>';
  // Periodicidad completa
  h+='<div style="margin-bottom:6px"><label style="font-size:11px;font-weight:600;color:var(--text2);display:block;margin-bottom:3px">Periodicidad</label><div style="display:flex;gap:3px;flex-wrap:wrap;margin-bottom:4px">';
  [{v:0,l:'Diaria'},{v:2,l:'C/2 días'},{v:7,l:'Semanal'},{v:14,l:'C/2 sem.'},{v:-1,l:'Person.'}].forEach(function(o){var isC=o.v===-1&&showCustom;var isSel=o.v===freq||isC;h+='<button type="button" class="gz-freq-btn" data-val="'+o.v+'" onclick="_gzSetFreq('+o.v+')" style="flex:1;min-width:48px;padding:4px;border-radius:5px;border:1.5px solid '+(isSel?'var(--navy)':'transparent')+';background:'+(isSel?'rgba(46,62,110,.08)':'var(--s3)')+';cursor:pointer;font-size:9px;font-weight:600;color:'+(isSel?'var(--navy)':'var(--text3)')+'">'+o.l+'</button>';});
  h+='</div><div id="gzFreqCustomWrap" style="display:'+(showCustom?'':'none')+';margin-bottom:4px"><div style="display:flex;align-items:center;gap:4px;font-size:10px;color:var(--text2)">Cada <input type="number" id="gzFreqCustom" min="2" max="60" value="'+(showCustom?freq:3)+'" onchange="document.getElementById(\'gzFreq\').value=this.value" style="width:40px;padding:3px;border-radius:4px;border:1px solid var(--border);text-align:center;font-size:10px"> días</div></div>';
  h+='<div id="gzDiasWrap" style="display:'+(showDias?'':'none')+'"><div style="display:flex;gap:2px">';
  [{d:'lunes',l:'L'},{d:'martes',l:'M'},{d:'miercoles',l:'Mi'},{d:'jueves',l:'J'},{d:'viernes',l:'V'},{d:'sabado',l:'S'},{d:'domingo',l:'D'}].forEach(function(dd){var on=diasArr.indexOf(dd.d)>=0;h+='<button type="button" class="gz-dia-btn" data-dia="'+dd.d+'" onclick="_gzToggleDia(this)" style="width:26px;height:26px;border-radius:50%;border:1.5px solid '+(on?'var(--navy)':'var(--border)')+';background:'+(on?'rgba(46,62,110,.12)':'#fff')+';cursor:pointer;font-size:9px;font-weight:600;color:'+(on?'var(--navy)':'var(--text3)')+';display:flex;align-items:center;justify-content:center">'+dd.l+'</button>';});
