// ═══ LAYOUT CONFIG MODAL ═══
function _gaLayoutConfig(){
  var prev=document.getElementById('gaConfigModal');if(prev)prev.remove();
  var tipos=_ZONA_TIPOS.map(function(t){return '<tr><td style="font-weight:700;font-family:var(--font-m);font-size:11px">'+t.prefix+'</td><td>'+t.v+'</td><td><input type="text" value="'+t.l+'" data-tipo="'+t.v+'" class="gc-label" style="width:100%;padding:3px 6px;border:1px solid var(--border);border-radius:4px;font-size:11px"></td><td style="color:var(--text3);font-size:10px;width:28px;text-align:center">'+(_ZONA_ICONS[t.v]?'✓':'—')+'</td></tr>';}).join('');
  var h='<div id="gaConfigModal" style="position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:1200;display:flex;align-items:center;justify-content:center;padding:16px"><div style="background:#fff;border-radius:14px;width:95%;max-width:500px;max-height:80vh;overflow:hidden;display:flex;flex-direction:column" onclick="event.stopPropagation()"><div class="modal-header"><h2>⚙ Configuración del Layout</h2><button class="modal-close" onclick="document.getElementById(\'gaConfigModal\').remove()">✕</button></div><div style="flex:1;overflow-y:auto;padding:16px">';
  h+='<div style="font-size:11px;font-weight:700;color:var(--navy);margin-bottom:8px">TIPOS DE ZONA</div>';
  h+='<table style="width:100%;border-collapse:collapse;font-size:11px"><thead><tr style="background:var(--s2)"><th style="padding:4px 6px;text-align:left;font-size:9px">Prefijo</th><th style="padding:4px 6px;text-align:left;font-size:9px">Código</th><th style="padding:4px 6px;text-align:left;font-size:9px">Nombre visible</th><th style="font-size:9px">Icono</th></tr></thead><tbody>'+tipos+'</tbody></table>';
  h+='<div style="margin-top:16px;font-size:11px;font-weight:700;color:var(--navy);margin-bottom:8px">TOOLTIPS</div>';
  h+='<div style="font-size:10px;color:var(--text3);margin-bottom:8px">Al pasar el mouse sobre una zona se muestra: <b>Código · Nombre</b> + instrucción de limpieza según el prefijo del código.</div>';
  h+='<div style="margin-top:16px;font-size:11px;font-weight:700;color:var(--navy);margin-bottom:8px">LEYENDA</div>';
  h+='<div style="display:flex;gap:8px;flex-wrap:wrap;font-size:10px"><span>🟢 Limpio hoy</span><span>🟡 No toca hoy</span><span>🔴 Deshabilitado</span><span>🟣 Sobre mueble</span><span>⬜ Techo</span></div>';
  h+='</div><div class="modal-footer"><button class="btn btn-ghost" onclick="document.getElementById(\'gaConfigModal\').remove()">Cerrar</button><button class="btn btn-primary" onclick="_gaApplyConfig()">Aplicar cambios</button></div></div></div>';
  document.body.insertAdjacentHTML('beforeend',h);
  document.getElementById('gaConfigModal').addEventListener('click',function(e){if(e.target===this)this.remove();});
}
function _gaApplyConfig(){
  document.querySelectorAll('.gc-label').forEach(function(inp){
    var tipo=inp.dataset.tipo,val=inp.value.trim();
    var t=_ZONA_TIPOS.find(function(x){return x.v===tipo});
    if(t&&val)t.l=val;
  });
  document.getElementById('gaConfigModal')?.remove();
  _glmR();
  showToast('Configuración aplicada','success');
}

// ═══ INJECT CONFIG BUTTON into layout modal after it opens ═══
var _origGaAbrirLayout=gaAbrirLayoutModal;
gaAbrirLayoutModal=function(){
  _origGaAbrirLayout();
  setTimeout(function(){
    var hdr=document.querySelector('#gaLayoutModal [style*="display:flex"][style*="gap:4px"]');
    if(hdr&&!hdr.querySelector('.ga-cfg-btn')){
      var btn=document.createElement('button');btn.className='btn btn-ghost btn-xs ga-cfg-btn';btn.textContent='⚙';btn.onclick=_gaLayoutConfig;
      var saveBtn=hdr.querySelector('[onclick*="gaLayoutSave"]');
      if(saveBtn)hdr.insertBefore(btn,saveBtn);
    }
  },100);
};
